//! The frame codec against the golden frames in `tests/golden/` (DIST-E8-T01; RFC-0031 §6.1,
//! §6.2, §6.7, §6.9; ADR-0307 items 1–2).
//!
//! The golden frames are generated by [`spec`], an encoder written from RFC-0031's tables with a
//! bit-by-bit CRC32C, and checked in as annotated hex. The tests check, for every golden frame,
//! that the file matches the tables, that the codec decodes it to the expected message and
//! encodes that message to the same bytes, and that corrupting any byte is detected.
//!
//! `SYNTROPY_BLESS_GOLDEN=1` rewrites the files from [`spec`]. A changed golden frame changes the
//! wire format, which needs a wire-minor bump (ADR-0307 item 1).

mod activation;
mod collective;
mod spec;

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use proptest::prelude::*;
use syntropy_core::plan::WireDType;
use syntropy_core::{ErrorClass, InstanceId, PlanEpoch, StageIx};
use syntropy_net::frame::{
    Close, Control, ControlSpec, CredKind, Credit, Flags, Frame, FrameError, FrameType, Hello,
    HelloAck, MAX_CONTROL_EXT, Nacks, Ping, Purpose, WIRE_MINOR, code, crc32c, encode_to_vec,
};

const INSTANCE: u64 = 0x1122_3344_5566_7788;
const TERM: u64 = 3;
const SEQ: u64 = 41;
const ENCRYPTED: u16 = 1 << 2;
const KEY_PHASE: u16 = 1 << 4;

/// What a golden frame decodes to.
enum Expect {
    /// An unsealed control frame and its message.
    Control(Control<'static>),
    /// A sealed control frame: the message its plaintext holds, its `ctl_seq` and key phase.
    Sealed {
        control: Control<'static>,
        ctl_seq: u64,
        key_phase: bool,
    },
    /// A data frame, whose extension and payload are opaque at this layer.
    Data {
        ftype: FrameType,
        flags: u16,
        step: u64,
        chan_seq: u64,
    },
}

struct Golden {
    name: &'static str,
    about: &'static str,
    bytes: Vec<u8>,
    expect: Expect,
}

fn leak(bytes: Vec<u8>) -> &'static [u8] {
    Vec::leak(bytes)
}

fn base(ftype: u8, flags: u16, step: u64, chan_seq: u64) -> spec::Base {
    spec::Base {
        ftype,
        flags,
        instance: INSTANCE,
        term: TERM,
        seq: SEQ,
        step,
        chan_seq,
    }
}

fn epoch() -> PlanEpoch {
    PlanEpoch {
        term: TERM,
        seq: SEQ,
    }
}

fn control_spec() -> ControlSpec {
    ControlSpec {
        wire_minor: WIRE_MINOR,
        flags: Flags::default(),
        instance: InstanceId(INSTANCE),
        epoch: epoch(),
    }
}

fn hello_ext(purpose: u8, wire_dtype: u8, cred_kind: u16, resume_from: Option<u64>) -> Vec<u8> {
    spec::hello_ext(&spec::HelloExt {
        purpose,
        wire_minor_max: 1,
        proto_major: 1,
        capabilities: 0x111,
        instance: INSTANCE,
        term: TERM,
        seq: SEQ,
        from_stage: 0,
        to_stage: 1,
        lane: 0,
        wire_dtype,
        slot_size: 1 << 20,
        recv_slots: 64,
        cred_kind,
        channel_token: if resume_from.is_some() {
            0xDEAD_BEEF_0000_0001
        } else {
            0
        },
        resume_from,
    })
}

fn hello(purpose: Purpose, wire_dtype: Option<WireDType>, cred_kind: CredKind) -> Hello {
    Hello {
        purpose,
        wire_minor_max: 1,
        proto_major: 1,
        capabilities: 0x111,
        instance: InstanceId(INSTANCE),
        epoch: epoch(),
        from_stage: StageIx(0),
        to_stage: StageIx(1),
        lane: 0,
        wire_dtype,
        slot_size: 1 << 20,
        recv_slots: 64,
        cred_kind,
        channel_token: 0,
        resume_from: None,
    }
}

fn credit(
    ack: u64,
    limit: u64,
    echo: u64,
    delay: u32,
    sack: bool,
    reset: bool,
    nacks: &[u64],
) -> Credit {
    Credit {
        ack_seq: ack,
        limit_seq: limit,
        echo_seq: echo,
        echo_delay_ns: delay,
        sack,
        reset,
        nacks: Nacks::new(nacks).unwrap(),
    }
}

fn goldens() -> Vec<Golden> {
    let mut all = Vec::new();

    let cred = spec::fill(1, 168);
    all.push(Golden {
        name: "hello",
        about: "Hello on an Activations channel, F32, with a DataPlaneCredential",
        bytes: spec::frame(&base(0x0A, 0, 0, 0), &hello_ext(1, 1, 1, None), &cred),
        expect: Expect::Control(Control::Hello {
            hello: hello(
                Purpose::Activations,
                Some(WireDType::F32),
                CredKind::DataPlaneCredential,
            ),
            credential: leak(cred),
        }),
    });

    let cred = spec::fill(2, 168);
    all.push(Golden {
        name: "hello-reconnect",
        about: "reconnect Hello on a Tokens channel: resume_from 1001 at extension offset 64",
        bytes: spec::frame(&base(0x0A, 0, 0, 0), &hello_ext(2, 0, 1, Some(1001)), &cred),
        expect: Expect::Control(Control::Hello {
            hello: Hello {
                channel_token: 0xDEAD_BEEF_0000_0001,
                resume_from: Some(1001),
                ..hello(Purpose::Tokens, None, CredKind::DataPlaneCredential)
            },
            credential: leak(cred),
        }),
    });

    let cred = spec::fill(3, 192);
    all.push(Golden {
        name: "hello-blob",
        about: "Hello opening a blob stream (purpose 8) with an AdmissionCert",
        bytes: spec::frame(&base(0x0A, 0, 0, 0), &hello_ext(8, 0, 2, None), &cred),
        expect: Expect::Control(Control::Hello {
            hello: hello(Purpose::BlobStream, None, CredKind::AdmissionCert),
            credential: leak(cred),
        }),
    });

    let cred = spec::fill(4, 168);
    all.push(Golden {
        name: "hello-ack",
        about: "HelloAck accepting the channel, with the acceptor's credential",
        bytes: spec::frame(
            &base(0x0B, 0, 0, 0),
            &spec::hello_ack_ext(0, 1, 0x111, 64, 1 << 20, 64, 1),
            &cred,
        ),
        expect: Expect::Control(Control::HelloAck {
            ack: HelloAck {
                status: code::OK,
                wire_minor: 1,
                capabilities: 0x111,
                limit_seq: 64,
                slot_size: 1 << 20,
                recv_slots: 64,
                cred_kind: Some(CredKind::DataPlaneCredential),
            },
            credential: leak(cred),
        }),
    });

    let reason = "ack timeout after 3 retries";
    all.push(Golden {
        name: "close",
        about: "Close AckTimeout (0x0208) with last_seq 1000 at extension offset 8 and a reason",
        bytes: spec::frame(
            &base(0x0C, 0, 0, 0),
            &spec::close_ext(0x0208, 1000),
            reason.as_bytes(),
        ),
        expect: Expect::Control(Control::Close {
            close: Close {
                code: code::ACK_TIMEOUT,
                last_seq: 1000,
            },
            reason,
        }),
    });

    all.push(Golden {
        name: "credit",
        about: "Credit: ack 1000, limit 1064, echoing 1000 after 2.5 µs",
        bytes: spec::frame(
            &base(0x04, 0, 0, 0),
            &spec::credit_ext(1000, 1064, 1000, 2500, 0, &[]),
            &[],
        ),
        expect: Expect::Control(Control::Credit(credit(
            1000,
            1064,
            1000,
            2500,
            false,
            false,
            &[],
        ))),
    });

    all.push(Golden {
        name: "credit-sack",
        about: "Credit with SACK and three NACKs",
        bytes: spec::frame(
            &base(0x04, 0, 0, 0),
            &spec::credit_ext(990, 1054, 1000, 1800, 1, &[991, 993, 997]),
            &[],
        ),
        expect: Expect::Control(Control::Credit(credit(
            990,
            1054,
            1000,
            1800,
            true,
            false,
            &[991, 993, 997],
        ))),
    });

    let sixteen: Vec<u64> = (1..=16).map(|i| 2000 + 2 * i).collect();
    all.push(Golden {
        name: "credit-16-nacks",
        about: "Credit with the most NACKs, 16: a 160-byte extension padded to 192",
        bytes: spec::frame(
            &base(0x04, 0, 0, 0),
            &spec::credit_ext(2000, 2064, 2033, 900, 1, &sixteen),
            &[],
        ),
        expect: Expect::Control(Control::Credit(credit(
            2000, 2064, 2033, 900, true, false, &sixteen,
        ))),
    });

    all.push(Golden {
        name: "credit-reset",
        about: "Credit with RESET: the receiver lost its state",
        bytes: spec::frame(
            &base(0x04, 0, 0, 0),
            &spec::credit_ext(0, 64, 0, 0, 2, &[]),
            &[],
        ),
        expect: Expect::Control(Control::Credit(credit(0, 64, 0, 0, false, true, &[]))),
    });

    all.push(Golden {
        name: "ping",
        about: "Ping request",
        bytes: spec::frame(
            &base(0x10, 0, 0, 0),
            &spec::ping_ext(1_700_000_000_123_456_789, 0),
            &[],
        ),
        expect: Expect::Control(Control::Ping(Ping {
            origin_ns: 1_700_000_000_123_456_789,
            reply: false,
        })),
    });

    all.push(Golden {
        name: "ping-reply",
        about: "Ping reply",
        bytes: spec::frame(
            &base(0x10, 0, 0, 0),
            &spec::ping_ext(1_700_000_000_123_456_789, 1),
            &[],
        ),
        expect: Expect::Control(Control::Ping(Ping {
            origin_ns: 1_700_000_000_123_456_789,
            reply: true,
        })),
    });

    // Sealed control frames: the extension past 16 bytes and the payload are ciphertext, the
    // payload ending in the 16-byte tag; `step` carries `ctl_seq`.
    all.push(Golden {
        name: "sealed-credit-phase0",
        about: "sealed Credit, KEY_PHASE 0, ctl_seq 1 in step; the payload is the tag alone",
        bytes: spec::frame(
            &base(0x04, ENCRYPTED, 1, 0),
            &spec::sealed_ext(&spec::credit_ext(1000, 1064, 1000, 2500, 0, &[]), 0x40),
            &spec::fill(0x90, 16),
        ),
        expect: Expect::Sealed {
            control: Control::Credit(credit(1000, 1064, 1000, 2500, false, false, &[])),
            ctl_seq: 1,
            key_phase: false,
        },
    });

    all.push(Golden {
        name: "sealed-ping-phase1",
        about: "sealed Ping, KEY_PHASE 1, ctl_seq 7 in step",
        bytes: spec::frame(
            &base(0x10, ENCRYPTED | KEY_PHASE, 7, 0),
            &spec::sealed_ext(&spec::ping_ext(42, 0), 0x50),
            &spec::fill(0xA0, 16),
        ),
        expect: Expect::Sealed {
            control: Control::Ping(Ping {
                origin_ns: 42,
                reply: false,
            }),
            ctl_seq: 7,
            key_phase: true,
        },
    });

    let reason = "re-plan";
    all.push(Golden {
        name: "sealed-close-phase1",
        about: "sealed Close, KEY_PHASE 1, ctl_seq 8: ciphertext reason, then the tag",
        bytes: spec::frame(
            &base(0x0C, ENCRYPTED | KEY_PHASE, 8, 0),
            &spec::sealed_ext(&spec::close_ext(0x020C, 512), 0x60),
            &spec::fill(0xB0, reason.len() + 16),
        ),
        expect: Expect::Sealed {
            control: Control::Close {
                close: Close {
                    code: code::EDGE_DEMOTED,
                    last_seq: 512,
                },
                reason,
            },
            ctl_seq: 8,
            key_phase: true,
        },
    });

    // Data frames: the base header with an opaque extension and payload.
    all.push(Golden {
        name: "data-activation",
        about: "Activation data frame: chan_seq 1, step 12, FIRST_OF_SEQ and HAS_TRACE, 128 B extension",
        bytes: spec::frame(
            &base(0x01, (1 << 3) | 1, 12, 1),
            &spec::fill(0x11, 128),
            &spec::fill(0x22, 256),
        ),
        expect: Expect::Data {
            ftype: FrameType::Activation,
            flags: (1 << 3) | 1,
            step: 12,
            chan_seq: 1,
        },
    });

    all.push(Golden {
        name: "data-sealed-phase1",
        about: "sealed Token data frame, KEY_PHASE 1, chan_seq 9; ciphertext and tag",
        bytes: spec::frame(
            &base(0x02, ENCRYPTED | KEY_PHASE, 0, 9),
            &spec::fill(0x33, 64),
            &spec::fill(0x44, 48 + 16),
        ),
        expect: Expect::Data {
            ftype: FrameType::Token,
            flags: ENCRYPTED | KEY_PHASE,
            step: 0,
            chan_seq: 9,
        },
    });

    all
}

fn golden_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

/// The golden frame's bytes, from its checked-in file.
fn read_golden(name: &str) -> Vec<u8> {
    let path = golden_dir().join(format!("{name}.hex"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    spec::from_hex(&text)
}

#[test]
fn golden_files_match_the_spec_tables() {
    let goldens = goldens();
    if std::env::var_os("SYNTROPY_BLESS_GOLDEN").is_some() {
        std::fs::create_dir_all(golden_dir()).unwrap();
        for golden in &goldens {
            let text = spec::to_hex(golden.name, golden.about, &golden.bytes);
            std::fs::write(golden_dir().join(format!("{}.hex", golden.name)), text).unwrap();
        }
    }
    for golden in &goldens {
        assert_eq!(
            read_golden(golden.name),
            golden.bytes,
            "{} differs from the tables",
            golden.name
        );
    }
    // No golden file is left over from a frame the list no longer has.
    let listed: BTreeSet<String> = goldens.iter().map(|g| format!("{}.hex", g.name)).collect();
    let on_disk: BTreeSet<String> = std::fs::read_dir(golden_dir())
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .filter(|name| name.ends_with(".hex"))
        .collect();
    assert_eq!(on_disk, listed);
}

#[test]
fn golden_frames_round_trip() {
    for golden in goldens() {
        let bytes = read_golden(golden.name);
        let frame = Frame::decode(&bytes).unwrap_or_else(|e| panic!("{}: {e}", golden.name));
        assert_eq!(
            frame.header.frame_len(),
            bytes.len() as u64,
            "{}",
            golden.name
        );
        assert_eq!(frame.header.spec.wire_minor, WIRE_MINOR);
        assert_eq!(frame.header.spec.instance, InstanceId(INSTANCE));
        assert_eq!(frame.header.spec.epoch, epoch());
        // Raw round trip: the decoded fields and bytes encode to the same frame.
        let again = encode_to_vec(&frame.header.spec, frame.ext, frame.payload).unwrap();
        assert_eq!(again, bytes, "{}: raw re-encode", golden.name);
        match golden.expect {
            Expect::Control(control) => {
                assert_eq!(frame.control(), Ok(control), "{}", golden.name);
                assert_eq!(
                    control.encode_to_vec(&control_spec()).unwrap(),
                    bytes,
                    "{}",
                    golden.name
                );
            }
            Expect::Sealed {
                control,
                ctl_seq,
                key_phase,
            } => {
                let header = frame.header;
                assert_eq!(header.spec.ftype, control.ftype());
                assert!(header.spec.flags.encrypted(), "{}", golden.name);
                assert_eq!(header.spec.flags.key_phase(), key_phase, "{}", golden.name);
                assert_eq!(header.ctl_seq(), Some(ctl_seq), "{}", golden.name);
                assert_eq!(
                    &bytes[32..40],
                    &ctl_seq.to_le_bytes(),
                    "{}: ctl_seq in step",
                    golden.name
                );
                assert_eq!(header.spec.chan_seq, 0);
                // The plaintext routing prefix is the message's own first 16 extension bytes.
                let mut ext = [0; MAX_CONTROL_EXT];
                let ext_len = control.write_ext(&mut ext).unwrap();
                assert_eq!(frame.ext.len(), ext_len, "{}", golden.name);
                assert_eq!(&frame.ext[..16], &ext[..16], "{}", golden.name);
                assert_eq!(
                    frame.payload.len(),
                    control.payload().len() + 16,
                    "{}: tag",
                    golden.name
                );
                assert_eq!(frame.control(), Err(FrameError::Sealed(control.ftype())));
            }
            Expect::Data {
                ftype,
                flags,
                step,
                chan_seq,
            } => {
                assert_eq!(frame.header.spec.ftype, ftype);
                assert_eq!(frame.header.spec.flags, Flags(flags));
                assert_eq!(frame.header.spec.step, step);
                assert_eq!(frame.header.spec.chan_seq, chan_seq);
                assert_eq!(frame.control(), Err(FrameError::NotControl(ftype)));
            }
        }
    }
}

#[test]
fn the_goldens_cover_sealed_control_frames_in_both_key_phases() {
    let mut phases = BTreeSet::new();
    for golden in goldens() {
        if let Expect::Sealed {
            key_phase, ctl_seq, ..
        } = golden.expect
        {
            assert!(ctl_seq >= 1);
            phases.insert(key_phase);
        }
    }
    assert_eq!(phases, BTreeSet::from([false, true]));
    // `Close`'s `last_seq` sits at extension offset 8.
    let close = read_golden("close");
    assert_eq!(&close[64 + 8..64 + 16], &1000u64.to_le_bytes());
}

/// The criterion "a corrupted byte anywhere is detected": every byte of every golden frame, each
/// of its eight single-bit flips and its complement.
#[test]
fn a_corrupted_byte_anywhere_is_detected() {
    let mut checked = 0;
    for golden in goldens() {
        let bytes = read_golden(golden.name);
        // The untouched frame decodes, so each refusal below is the corruption's doing.
        assert!(
            Frame::decode(&bytes).is_ok(),
            "{} does not decode",
            golden.name
        );
        for at in 0..bytes.len() {
            for mask in [1, 2, 4, 8, 16, 32, 64, 128, 0xFF] {
                let mut corrupt = bytes.clone();
                corrupt[at] ^= mask;
                assert!(
                    Frame::decode(&corrupt).is_err(),
                    "{}: byte {at} ^ {mask:#04x} was accepted",
                    golden.name
                );
                checked += 1;
            }
        }
    }
    assert!(checked > 30_000, "{checked} corruptions checked");
}

#[test]
fn every_frame_type_code_is_known_and_an_unknown_one_is_refused() {
    let golden = read_golden("ping");
    for code in 0..=255u8 {
        let mut bytes = golden.clone();
        bytes[5] = code;
        // Re-seal the header CRC so only the frame type differs.
        let mut covered = bytes[..60].to_vec();
        covered.extend_from_slice(&bytes[64..128]);
        bytes[60..64].copy_from_slice(&spec::crc32c(&covered).to_le_bytes());
        let result = Frame::decode(&bytes);
        match FrameType::from_code(code) {
            None => assert_eq!(
                result,
                Err(FrameError::UnknownFrameType(code)),
                "{code:#04x}"
            ),
            Some(_) => assert!(
                !matches!(result, Err(FrameError::UnknownFrameType(_))),
                "{code:#04x}"
            ),
        }
    }
    assert_eq!(
        FrameError::UnknownFrameType(0x13).code(),
        Some(code::UNKNOWN_FRAME_TYPE)
    );
    // A refusal, so never `Internal` (RFC-0060 §10.2); the Close still carries 0x0204.
    assert_eq!(
        FrameError::UnknownFrameType(0x13).class(),
        ErrorClass::Unsupported
    );
}

/// The classes RFC-0060 §10.2 allows a decoder's refusal of untrusted bytes: never `Internal`.
const REFUSAL_CLASSES: [ErrorClass; 4] = [
    ErrorClass::Integrity,
    ErrorClass::InvalidRequest,
    ErrorClass::Auth,
    ErrorClass::Unsupported,
];

/// RFC-0060 §10.2's properties for one input, as the criterion states them: decoding `bytes`
/// does not panic; a refusal has an allowed class; an accepted frame lies within `bytes`, reads
/// nothing past its declared lengths (`trailer` appended after it changes nothing), and
/// re-encodes to the same bytes.
fn decodes_safely(bytes: &[u8], trailer: &[u8]) -> Result<(), TestCaseError> {
    match Frame::decode(bytes) {
        Err(error) => {
            prop_assert!(
                REFUSAL_CLASSES.contains(&error.class()),
                "{error}: {:?}",
                error.class()
            );
        }
        Ok(frame) => {
            let len = frame.header.frame_len() as usize;
            prop_assert!(len <= bytes.len());
            prop_assert_eq!(frame.ext.len(), frame.header.ext_len as usize);
            prop_assert_eq!(frame.payload.len(), frame.header.payload_len as usize);
            let mut longer = bytes[..len].to_vec();
            longer.extend_from_slice(trailer);
            prop_assert_eq!(Frame::decode(&longer), Ok(frame));
            prop_assert_eq!(Frame::decode(&bytes[..len]), Ok(frame));
            let again = encode_to_vec(&frame.header.spec, frame.ext, frame.payload).unwrap();
            prop_assert_eq!(&again[..], &bytes[..len]);
        }
    }
    Ok(())
}

/// Recomputes `payload_crc` and `header_crc` of a frame whose lengths match its buffer.
fn reseal(bytes: &mut [u8]) {
    let ext_len = u32::from_le_bytes(bytes[48..52].try_into().unwrap()) as usize;
    let payload = &bytes[64 + ext_len..];
    let payload_crc = if payload.is_empty() {
        0
    } else {
        spec::crc32c(payload)
    };
    bytes[56..60].copy_from_slice(&payload_crc.to_le_bytes());
    let mut covered = bytes[..60].to_vec();
    covered.extend_from_slice(&bytes[64..64 + ext_len]);
    bytes[60..64].copy_from_slice(&spec::crc32c(&covered).to_le_bytes());
}

proptest! {
    /// The codec's CRC32C, hardware or table, equals the bit-by-bit reference.
    #[test]
    fn crc32c_matches_the_bitwise_reference(data in proptest::collection::vec(any::<u8>(), 0..2048)) {
        prop_assert_eq!(crc32c(&data), spec::crc32c(&data));
    }

    /// Decoding arbitrary bytes never panics and holds RFC-0060 §10.2's properties: see
    /// [`decodes_safely`].
    #[test]
    fn arbitrary_bytes_decode_safely(
        bytes in proptest::collection::vec(any::<u8>(), 0..600),
        trailer in proptest::collection::vec(any::<u8>(), 0..64),
    ) {
        decodes_safely(&bytes, &trailer)?;
    }

    /// Golden frames with several bytes changed hold the same properties.
    #[test]
    fn mutated_goldens_decode_safely(
        which in any::<usize>(),
        edits in proptest::collection::vec((any::<usize>(), any::<u8>()), 1..6),
        trailer in proptest::collection::vec(any::<u8>(), 0..64),
    ) {
        let goldens = goldens();
        let mut bytes = read_golden(goldens[which % goldens.len()].name);
        for (at, value) in edits {
            let len = bytes.len();
            bytes[at % len] = value;
        }
        decodes_safely(&bytes, &trailer)?;
    }

    /// Golden frames with header, extension or payload bytes changed and both CRCs recomputed, so
    /// the changes reach the frame rules and the typed control parser: no panic, and every
    /// refusal at either layer is classified.
    #[test]
    fn resealed_mutations_decode_safely(
        which in any::<usize>(),
        edits in proptest::collection::vec((any::<usize>(), any::<u8>()), 1..6),
    ) {
        let goldens = goldens();
        let mut bytes = read_golden(goldens[which % goldens.len()].name);
        for (at, value) in edits {
            // Leave magic, the lengths and the CRCs alone: the frame stays self-consistent.
            let at = at % bytes.len();
            if (4..48).contains(&at) || at >= 64 {
                bytes[at] = value;
            }
        }
        reseal(&mut bytes);
        decodes_safely(&bytes, &[])?;
        if let Ok(frame) = Frame::decode(&bytes)
            && let Err(error) = frame.control()
        {
            prop_assert!(REFUSAL_CLASSES.contains(&error.class()), "{error}: {:?}", error.class());
        }
    }

    /// The typed control parser on arbitrary extensions and payloads: no panic, every refusal is
    /// classified, and an accepted message encodes to a frame that decodes to it again.
    #[test]
    fn arbitrary_control_bodies_parse_safely(
        ftype in prop::sample::select(vec![
            FrameType::Hello, FrameType::HelloAck, FrameType::Close, FrameType::Credit, FrameType::Ping,
        ]),
        ext in proptest::collection::vec(any::<u8>(), 0..256),
        payload in proptest::collection::vec(any::<u8>(), 0..300),
    ) {
        match Control::parse(ftype, &ext, &payload) {
            Err(error) => {
                prop_assert!(REFUSAL_CLASSES.contains(&error.class()), "{error}: {:?}", error.class());
            }
            Ok(control) => {
                let bytes = control.encode_to_vec(&control_spec()).unwrap();
                prop_assert_eq!(Frame::decode(&bytes).unwrap().control(), Ok(control));
            }
        }
    }

    /// Any valid credit or ping round-trips through a frame.
    #[test]
    fn credits_and_pings_round_trip(
        ack in any::<u64>(),
        window in 0u64..1 << 20,
        echo in any::<u64>(),
        delay in any::<u32>(),
        sack in any::<bool>(),
        reset in any::<bool>(),
        nacks in proptest::collection::vec(any::<u64>(), 0..=16),
        origin in any::<u64>(),
        reply in any::<bool>(),
    ) {
        let messages = [
            Control::Credit(credit(ack, ack.saturating_add(window), echo, delay, sack, reset, &nacks)),
            Control::Ping(Ping { origin_ns: origin, reply }),
        ];
        for message in messages {
            let bytes = message.encode_to_vec(&control_spec()).unwrap();
            let frame = Frame::decode(&bytes).unwrap();
            prop_assert_eq!(frame.control().unwrap(), message);
        }
    }
}
